changeSet.sql:
INSERT INTO practice_revision ( practice_id, revision_number, criteria, created_at, slug, name, applies_to, trigger_events, precompute_script, why_it_matters, what_good_looks_like, area_slug, area_name, area_description, area_icon, area_color, evidence_declaration ) SELECT practice.id, COALESCE(max_revision.revision_number, 0) + 1, practice.criteria, CURRENT_TIMESTAMP, practice.slug, practice.name, practice.applies_to, practice.trigger_events, practice.precompute_script, practice.why_it_matters, practice.what_good_looks_like, area.slug, area.name, area.description, area.icon, area.color, practice.evidence_declaration FROM practice LEFT JOIN practice_area area ON area.id = practice.practice_area_id LEFT JOIN ( SELECT practice_id, max(revision_number) AS revision_number FROM practice_revision GROUP BY practice_id ) max_revision ON max_revision.practice_id = practice.id;
UPDATE practice SET current_revision_id = current_revision.id FROM practice_revision current_revision WHERE current_revision.practice_id = practice.id AND current_revision.revision_number = ( SELECT max(candidate.revision_number) FROM practice_revision candidate WHERE candidate.practice_id = practice.id );
CREATE OR REPLACE FUNCTION enforce_practice_revision_immutability() RETURNS trigger LANGUAGE plpgsql AS $immutable_revision$ BEGIN IF NEW.practice_id = OLD.practice_id AND NEW.revision_number = OLD.revision_number AND NEW.created_at = OLD.created_at AND NEW.slug IS NOT DISTINCT FROM OLD.slug AND NEW.name IS NOT DISTINCT FROM OLD.name AND NEW.applies_to IS NOT DISTINCT FROM OLD.applies_to AND NEW.trigger_events IS NOT DISTINCT FROM OLD.trigger_events AND NEW.criteria = OLD.criteria AND NEW.precompute_script IS NOT DISTINCT FROM OLD.precompute_script AND NEW.evidence_declaration IS NOT DISTINCT FROM OLD.evidence_declaration AND NEW.why_it_matters IS NOT DISTINCT FROM OLD.why_it_matters AND NEW.what_good_looks_like IS NOT DISTINCT FROM OLD.what_good_looks_like AND NEW.area_slug IS NOT DISTINCT FROM OLD.area_slug AND NEW.area_name IS NOT DISTINCT FROM OLD.area_name AND NEW.area_description IS NOT DISTINCT FROM OLD.area_description AND NEW.area_icon IS NOT DISTINCT FROM OLD.area_icon AND NEW.area_color IS NOT DISTINCT FROM OLD.area_color AND ( NEW.detection_fingerprint IS NOT DISTINCT FROM OLD.detection_fingerprint OR OLD.detection_fingerprint IS NULL ) THEN RETURN NEW; END IF; RAISE EXCEPTION 'practice revisions are immutable' USING ERRCODE = '55000'; END; $immutable_revision$;
CREATE OR REPLACE FUNCTION enforce_practice_current_revision_projection() RETURNS trigger LANGUAGE plpgsql AS $current_projection$ BEGIN IF NOT EXISTS ( SELECT 1 FROM practice practice JOIN practice_revision revision ON revision.id = practice.current_revision_id AND revision.practice_id = practice.id LEFT JOIN practice_area area ON area.id = practice.practice_area_id WHERE practice.id = NEW.id AND revision.slug = practice.slug AND revision.name = practice.name AND revision.applies_to = practice.applies_to AND revision.trigger_events = practice.trigger_events AND revision.criteria = practice.criteria AND revision.precompute_script IS NOT DISTINCT FROM practice.precompute_script AND revision.evidence_declaration = practice.evidence_declaration AND revision.why_it_matters IS NOT DISTINCT FROM practice.why_it_matters AND revision.what_good_looks_like IS NOT DISTINCT FROM practice.what_good_looks_like AND revision.area_slug IS NOT DISTINCT FROM area.slug ) THEN RAISE EXCEPTION 'practice current revision does not match its current projection' USING ERRCODE = '23514'; END IF; RETURN NULL; END; $current_projection$;
DROP TRIGGER practice_requires_current_revision_projection ON practice; CREATE CONSTRAINT TRIGGER practice_requires_current_revision_projection AFTER INSERT OR UPDATE OF current_revision_id, slug, name, applies_to, trigger_events, criteria, precompute_script, evidence_declaration, why_it_matters, what_good_looks_like, practice_area_id ON practice DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION enforce_practice_current_revision_projection();

rollback.sql:
