CREATE OR REPLACE FUNCTION enforce_practice_current_revision_projection() RETURNS trigger LANGUAGE plpgsql AS $current_projection$ BEGIN IF NOT EXISTS ( SELECT 1 FROM practice practice JOIN practice_revision revision ON revision.id = practice.current_revision_id AND revision.practice_id = practice.id LEFT JOIN practice_area area ON area.id = practice.practice_area_id WHERE practice.id = NEW.id AND revision.slug = practice.slug AND revision.name = practice.name AND revision.applies_to = practice.applies_to AND revision.trigger_events = practice.trigger_events AND revision.criteria = practice.criteria AND revision.precompute_script IS NOT DISTINCT FROM practice.precompute_script AND revision.why_it_matters IS NOT DISTINCT FROM practice.why_it_matters AND revision.what_good_looks_like IS NOT DISTINCT FROM practice.what_good_looks_like AND revision.area_slug IS NOT DISTINCT FROM area.slug ) THEN RAISE EXCEPTION 'practice current revision does not match its current projection' USING ERRCODE = '23514'; END IF; RETURN NULL; END; $current_projection$;
